        background-color: transparent;

        &::before {
            content: '';
            position: fixed;
            inset: 0;
            z-index: -1;
            background-color: color-mix(in oklab, var(--stone-12), transparent 20%);
            backdrop-filter: blur(3px);
        }
        .region-popover-header {
            display: flex;
            justify-content: space-between;
            margin-block-end: var(--spacing-6);

        }
        .region-popover-content {
            background: white;
            display: flex;
            gap: var(--spacing-2-5);
            flex-direction: column;
            padding: var(--spacing-5);

            & > button {
                display: block;
                color: white;
                background-color: #888;
                text-align: center;
                padding-block: var(--spacing-3);

                &:first-of-type {
                    background-color: #fa4f0c;
                    margin-block-start: var(--spacing-3);
                }
                &:last-of-type {
                    margin-block-end: var(--spacing-3);
                }

                &:hover {
                    opacity: .8;
                }
            }
            p {
                color: black;
                align-self: center;

                &:last-of-type {
                    opacity: .4;
                }
            }
        }
    }













