    .theme-switch {
        display: flex;
        align-items: center;

        .theme-slider {
            background: #f2f2f2;
            outline: 1px solid var(--stone-12);
            border-radius: 1000000rem;
            height: .6lh;
            aspect-ratio: 3;
            display: inline-block;
            margin-inline: var(--spacing-1);


            position: relative;

            &:before {
                content: '';
                position: absolute;
                left: 0%;
                height: 70%;
                margin:  5%;
                aspect-ratio: 1;
                border-radius: 1000000rem;
                background: #ff7a00;
                box-shadow: 0px 2px 4px  #00000040;


                width: unset;
                transition: .4s var(--ease-in-5);
            }
            &:after {
                content: '';
                position: absolute;

                left: 0%;
                height: 70%;
                margin: 5%;
                aspect-ratio: 1;
                border-radius: 1000000rem;
                background: #181818;
                box-shadow: 0px 2px 4px  #00000040;

                animation-name: theme-slide;
                animation-duration: .69s;
                animation-fill-mode: forwards;
                animation-direction: reverse;
                animation-timing-function: var(--ease-in-5);
            }

        }
        input {
            display: none;

            &:checked + .theme-slider:before {

                width: 90%;
            }
            &:checked + .theme-slider:after {
                animation-name: theme-slide-reverse;
            }
        }
    }
    @keyframes theme-slide-before {
        0% {
            width: unset;
        }
        50% {
            width: 90%;
        }
        100% {
            width: 90%;
        }
    }
    @keyframes theme-slide-reverse-before {
        0% {
            width: unset;
        }
        50% {
            width: 90%;
        }
        100% {
            width: 90%;
        }
    }
    @keyframes theme-slide {
        0% {
            width: unset;
            left: 0%;
            right: unset;
        }
        50% {
            width: 90%;
            left: 0%;
            right: unset;
        }
        51% {
            width: 90%;
            left: unset;
            right: 0%;
        }
        100% {
            width: unset;
            left: unset;
            right: 0%;
        }
    }
    @keyframes theme-slide-reverse {
        0% {
            width: unset;
            left: unset;
            right: 0%;
        }
        50% {
            width: 90%;
            left: unset;
            right: 0%;
        }
        51% {
            width: 90%;
            left: 0%;
            right: unset;
        }
        100% {
            width: unset;
            left: 0%;
            right: unset;
        }
