// Sync the checkbox with the initial state set by the <head> script
if (darkModeCheck) {
    darkModeCheck.checked = document.documentElement.classList.contains('darkmode');
}

const setTheme = (theme) => {
    localStorage.setItem('huskTheme', theme);
    if(theme === 'dark') {
        document.documentElement.classList.add('darkmode');
        if(darkModeCheck) darkModeCheck.checked = true;
    } else if (theme === 'light') {
        document.documentElement.classList.remove('darkmode');
        if(darkModeCheck) darkModeCheck.checked = false;
    }
}

// Listen for system theme changes
const match = window.matchMedia('(prefers-color-scheme: dark)');
match.addEventListener('change', (event) => {
    // Only auto-switch if the user hasn't forced a specific theme
    if (localStorage.getItem('huskTheme') === null) {
        setTheme(event.target.matches ? 'dark' : 'light');
    }
});

// Assuming you also want the checkbox to actually change the theme when clicked!
if (darkModeCheck) {
    darkModeCheck.addEventListener('change', (e) => {
        setTheme(e.target.checked ? 'dark' : 'light');
    });
}



